import app from 'flarum/admin/app';
import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import BumpLog from '../common/BumpLog';

/** Settings, permissions, then the bump log. */
export default class ResurfacePage extends ExtensionPage {
  sections(vnode) {
    const items = super.sections(vnode);
    items.add('resurfaceLog', m("div", {
      className: "ExtensionPage-settings ResurfaceAdmin-log"
    }, m("div", {
      className: "container"
    }, m("h3", {
      className: "ExtensionPage-subHeader"
    }, app.translator.trans('ernestdefoe-resurface.admin.log.title')), this.isEnabled() && m(BumpLog, {
      external: true,
      link: discussion => `${app.forum.attribute('baseUrl')}/d/${discussion.id()}`
    }))), -10);
    return items;
  }
}